input.function:
() => {
  const grab = (sel) => { const el = document.querySelector(sel); return el ? el.innerText.trim() : null; };
  const grabAttr = (sel, attr) => { const el = document.querySelector(sel); return el ? el.getAttribute(attr) : null; };
  // Look for common SPA hydration hooks
  const next = document.getElementById('__NEXT_DATA__');
  const remix = window.__remixContext;
  const ldjson = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => s.textContent.slice(0, 5000));
  return {
    url: location.href,
    title: document.title,
    h1: grab('h1'),
    h2: grab('h2'),
    body_text: document.body.innerText.slice(0, 2000),
    meta_description: grabAttr('meta[name="description"]', 'content'),
    og_title: grabAttr('meta[property="og:title"]', 'content'),
    og_description: grabAttr('meta[property="og:description"]', 'content'),
    og_site_name: grabAttr('meta[property="og:site_name"]', 'content'),
    has_next_data: !!next,
    next_data_first_5000: next ? next.textContent.slice(0, 5000) : null,
    has_remix: !!remix,
    ldjson_count: ldjson.length,
    ldjson_first: ldjson[0] || null,
    forms: Array.from(document.forms).length,
    apply_links: Array.from(document.querySelectorAll('a, button')).filter(e => /apply/i.test(e.innerText || '')).slice(0, 5).map(e => ({ tag: e.tagName, text: (e.innerText || '').trim().slice(0,80), href: e.href || null })),
  };
}
